  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = false,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO: 244-2003', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CPP_OLA1.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA1')
  WHERE ingest_batch = 'OLA1_CPP_2024_01' AND id IN ('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:373', 'OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:374', 'OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:375', 'OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:376', 'OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:377', 'OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:378', 'OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:379', 'OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:380');
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = false,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO: 195-2004', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CPP_OLA1.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA1')
  WHERE ingest_batch = 'OLA1_CPP_2024_01' AND id IN ('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:418', 'OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:419');
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA1_CPP_2024_01' AND revision_pendiente = false AND metadata->>'estado_v' = 'V5';
  IF n <> 480 THEN RAISE EXCEPTION 'postcondición visibles V5 = % (esperado 480)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA1_CPP_2024_01' AND es_norma_vigente = true AND NOT (metadata ? 'rol');
  IF n <> 468 THEN RAISE EXCEPTION 'postcondición PRIMARY vigentes = % (esperado 468)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA1_CPP_2024_01' AND es_norma_vigente = true AND metadata->>'rol' = 'CONTEXT';
  IF n <> 1 THEN RAISE EXCEPTION 'postcondición CONTEXT vigentes = % (esperado 1)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA1_CPP_2024_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 11 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 11)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA1_CPP_2024_01' AND es_norma_vigente IS NULL AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT pendientes = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA1_CPP_2024_01' AND es_norma_vigente = false AND NOT (metadata ? 'rol');
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición derogados PRIMARY (prohibido) = % (esperado 0)', n; END IF;
  UPDATE public.biblioteca_vectores b SET revision_pendiente = true,
    metadata = b.metadata || jsonb_build_object('sustituido_por_lote', 'OLA1_CPP_2024_01', 'sustituido_fecha', '2026-11-24', 'revision_pendiente_motivo', 'Sustituida por HN:CODIGO_PROCESAL_PENAL V5 (OLA1); oculta, no borrada')
  WHERE b.metadata->>'norm_id' = 'HN_CODIGO_PROCESAL_PENAL' AND b.id LIKE 'mayalex_normativos:cpp_1999_a%' AND b.revision_pendiente = false;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 480 THEN RAISE EXCEPTION 'legacy ocultadas: % (esperadas 480)', n; END IF;
END $do$;
COMMIT;
SELECT count(*) AS filas, count(*) FILTER (WHERE revision_pendiente = false) AS visibles, metadata->>'estado_v' AS estado_v,
  count(*) FILTER (WHERE es_norma_vigente = true AND NOT (metadata ? 'rol')) AS primary_vigentes,
  count(*) FILTER (WHERE metadata->>'rol' = 'CONTEXT') AS context,
  count(*) FILTER (WHERE es_norma_vigente = false) AS derogados,
  count(*) FILTER (WHERE embedding IS NOT NULL) AS con_embedding,
  count(*) FILTER (WHERE encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido) AS sha_ok
FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA1_CPP_2024_01' GROUP BY metadata->>'estado_v';
